// 말랑퍼즐 v6 — 3D 그림 (Three.js로 미리 그린 이미지, 2026-11-13)
// 블록 8개(7색+돌, 112px)와 동물 친구 그림(토끼·고양이·슬라임, 640×420)을 게임 안에 넣음 → 인터넷 없이도 그대로.
// 얼굴(눈·볼·입)은 원래 게임의 그림을 3D 블록 위에 겹쳐 그림.
(function(){
var SPR={"#6ef3ff":"data:image/webp;base64,","#fff36e":"data:image/webp;base64,","#d58bff":"data:image/webp;base64,","#7dffb0":"data:image/webp;base64,","#ff7fb0":"data:image/webp;base64,","#7f9bff":"data:image/webp;base64,","#ffb36e":"data:image/webp;base64,","#7d8c86":"data:image/webp;base64,"};
// 블록 v2(두툼하게 깎인 모서리) — 캡틴 "3번은 별로" → 쓰지 않음(첫 블록 그림 + 아래 광택을 씀)
var SPR_V2_UNUSED={"#6ef3ff":"data:image/webp;base64,","#fff36e":"data:image/webp;base64,","#d58bff":"data:image/webp;base64,","#7dffb0":"data:image/webp;base64,","#ff7fb0":"data:image/webp;base64,","#7f9bff":"data:image/webp;base64,","#ffb36e":"data:image/webp;base64,","#7d8c86":"data:image/webp;base64,"};
var ANI="data:image/webp;base64,";
// 캐릭터 7칸(200×200씩, 가로로 이어 붙인 한 장): 0 고양이 · 1 슬라임 · 2 구름 토끼 · 3 보라 슬라임 · 4 꿀 곰돌이 · 5 토끼 · 6 시무룩 토끼
var CH="data:image/webp;base64,";
try{
  // 3D 블록 그림을 한 번만 정의 → 게임에서는 <use>로 불러 씀(빠름)
  var ids={},defs='',i=0;
  for(var c in SPR){ids[c]='sp3d'+i;defs+='<image id="sp3d'+i+'" href="'+SPR[c]+'" x="-1" y="-1" width="34" height="34"/>';i++}
  defs+='<image id="ch3d" href="'+CH+'" x="0" y="0" width="1400" height="200"/>';
  document.body.insertAdjacentHTML('beforeend','<svg width="0" height="0" style="position:absolute;width:0;height:0" aria-hidden="true"><defs>'+defs+'</defs></svg>');
  var oldCandy=window.candy;
  // 블록 아래 그림자(판 위에서 입체감) + 3D 블록 + 처음 블록처럼 왼쪽 위에서 비춘 광택(흰 곡선·오른쪽 아래 반짝 점) + 원래 얼굴
  window.candy=function(x,y,c,k,stone){var id=ids[stone?'#7d8c86':c];if(!id)return oldCandy(x,y,c,k,stone);
    return '<rect x="'+(x+3)+'" y="'+(y+4.5)+'" width="29" height="29" rx="9" fill="#04120b" opacity=".32"/><use href="#'+id+'" x="'+x+'" y="'+y+'"/>'
      +'<path d="M'+(x+5)+','+(y+12)+' Q'+(x+5)+','+(y+5)+' '+(x+12)+','+(y+5)+' H'+(x+22)+' Q'+(x+27)+','+(y+5)+' '+(x+27)+','+(y+9)+' Q'+(x+16)+','+(y+10)+' '+(x+5)+','+(y+16)+'Z" fill="#fff" opacity="'+(stone?.3:.6)+'"/>'
      +'<circle cx="'+(x+25)+'" cy="'+(y+25)+'" r="2" fill="#fff" opacity=".5"/>'+(k==null||k<0?'':face(x,y,stone?4:k))};
  // 캐릭터 칸 하나 그리기 (i번 칸을 x,y에 w 크기로)
  var ch=function(i,x,y,w){return '<svg x="'+x+'" y="'+y+'" width="'+w+'" height="'+w+'" viewBox="'+(i*200)+' 0 200 200"><use href="#ch3d"/></svg>'};
  // 10단계마다 만나는 친구 5명(메뉴 동그라미·친구 창)
  for(var f=0;f<5&&f<FRIENDS.length;f++)(function(n){FRIENDS[n].art=function(){return ch(n,-70,-70,140)}})(f);
  // 창 속 토끼: 또 왔구나 · 토끼 도움 · 시무룩(실패)
  document.getElementById('wBunny').innerHTML=bub(-20,58)+ch(5,-62,-96,124);
  document.getElementById('helpBunny').innerHTML=bub(-10,56)+ch(5,-58,-70,116);
  document.getElementById('sadBunny').innerHTML=bub(-10,56)+ch(6,-58,-70,116);
  // 첫 화면·메뉴 그림: 3D 동물 친구 + 떠다니는 3D 블록
  var ani=function(x,y,w){return '<image class="float" href="'+ANI+'" x="'+x+'" y="'+y+'" width="'+w+'" height="'+(w*420/640)+'"/>'};
  document.getElementById('heroArt').innerHTML=floatC(-92,-128,.9,PAL[4],1,'float2')+floatC(86,-142,.75,PAL[1],0,'float')+floatC(100,-92,.6,PAL[0],-1,'float2')+floatC(-102,-84,.55,PAL[2],-1,'float')+ani(-152,-128,304);
  document.getElementById('menuArt').innerHTML=floatC(-90,-110,.8,PAL[1],0,'float2')+floatC(90,-120,.75,PAL[5],2,'float')+ani(-152,-128,304);
  // 게임 화면 아래 동물 장식도 3D로
  var fr=document.getElementById('frame');for(var n=0;n<3&&fr.lastElementChild;n++)fr.removeChild(fr.lastElementChild);
  fr.insertAdjacentHTML('beforeend','<image href="'+ANI+'" x="4" y="760" width="160" height="105"/>');
  window.__sprites3d=true;
}catch(e){window.__sprites3dErr=String(e)}
})();
